import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Agora setup (audio 1:1)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/chat-voice-calls/agora-setup.md","filePath":"feature/chat-voice-calls/agora-setup.md"}'),s={name:"feature/chat-voice-calls/agora-setup.md"};function o(r,e,l,c,p,d){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="agora-setup-audio-1-1" tabindex="-1">Agora setup (audio 1:1) <a class="header-anchor" href="#agora-setup-audio-1-1" aria-label="Permalink to &quot;Agora setup (audio 1:1)&quot;">​</a></h1><h2 id="account-configuration" tabindex="-1">Account configuration <a class="header-anchor" href="#account-configuration" aria-label="Permalink to &quot;Account configuration&quot;">​</a></h2><p>Create a user-owned Agora project with App ID + App Certificate authentication. Use the free allowance; review the current account billing controls and do not enable auto-recharge, recording or paid proxy features for this implementation. Free usage is a provider allowance, not a guarantee enforced by application code.</p><p>Set these only in the Business Service local environment, never in Web VITE_*:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">AGORA_APP_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;project App ID&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">AGORA_APP_CERTIFICATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;project App Certificate&gt;</span></span></code></pre></div><p>Do not commit credentials, paste them into tickets, or use Console temporary tokens as a production implementation. Restart Business after changing its environment.</p><h2 id="implemented-runtime" tabindex="-1">Implemented runtime <a class="header-anchor" href="#implemented-runtime" aria-label="Permalink to &quot;Implemented runtime&quot;">​</a></h2><p>POST <code>/api/v1/workspaces/{workspaceId}/chat/calls/{callId}/token</code> uses the authenticated actor, verifies both current DM memberships and an accepted, live call lease. The server derives the media channel and participant UID. Tokens expire after at most five minutes and never beyond the current call lease. Response is no-store. App Certificate never leaves Business. Tokens are not persisted in chat_calls.</p><p>Lifecycle APIs now support start/current/get/accept/decline/cancel/end plus connected and heartbeat acknowledgements. Call metadata uses compare-and-swap revisions and a unique active-participant index. Both participants must acknowledge media before ACTIVE. Ring timeout is 45 seconds; accepted lease is 60 seconds per participant.</p><p>Web DM header has a voice action; the workspace call bar supports answer/decline, hangup, microphone mute and explicit audio playback recovery. SDK is lazy-loaded after start/accept, creates microphone tracks only, and renews authorized tokens. Same-browser tabs coordinate microphone ownership using Web Locks. Calls are received while the Chat page is open; channel navigation preserves the session. Leaving Chat/logout releases local audio, and server lease expiry releases slots.</p><p>The publisher role supports SDK media publishing: the audio-only Web UI must only create microphone tracks. This token alone does not claim a provider-enforced video prohibition. Ending a call prevents renewal but does not instantly revoke an already issued token at Agora; short expiry limits this window.</p><h2 id="remaining-release-gates" tabindex="-1">Remaining release gates <a class="header-anchor" href="#remaining-release-gates" aria-label="Permalink to &quot;Remaining release gates&quot;">​</a></h2><p>Do not manually insert accepted call documents to bypass the lifecycle. Real Agora audio between two devices/networks has NOT been verified yet. Durable missed-call inbox, audible ringing/DND alert delivery and invitations outside the Chat route remain pending; no claim that the full notification scope is complete.</p><h2 id="migration-and-manual-test" tabindex="-1">Migration and manual test <a class="header-anchor" href="#migration-and-manual-test" aria-label="Permalink to &quot;Migration and manual test&quot;">​</a></h2><p>The user chose to apply <code>docs/database/migrations/2026-10-23-chat-voice-calls.js</code> manually. No Atlas writes were performed by this implementation.</p><p>In VS Code Playground, prepend <code>globalThis.BRANDHUB_CHAT_CALLS_APPLY = false;</code> to the complete migration script and execute the WHOLE script. Expect DRY_RUN, blocked=false. Then change false to true and execute the WHOLE script again. Do not run just the assignment: that only returns a boolean, not migration results. The script uses the explicit brandhub database and requires chat_channels baseline. Existing chat_calls metadata may need the updated validator reapplied for heartbeat fields. No calls are seeded; ChatSampleSeeder must never create live invitations.</p><p>Restart Business and refresh Web after migration. Use two accounts that belong to the same Workspace DIRECT channel, in separate browser profiles/devices. Open Chat on both sides. Call, answer, allow microphones and confirm two-way audio, mute, hangup and busy/timeout. Use headsets. For non-localhost deployment use HTTPS/WSS; an HTTP LAN IP does not satisfy microphone secure-context requirements.</p><p>Apply the reviewed chat_calls migration only after isolated validation and normal rollout approval. Existing chat messages must not be reset or reseeded for calls. After UI integration, verify two real accounts on separate networks, microphone permissions, DND/mute, expired tokens, busy state, disconnect and logout cleanup.</p><p>Official references:</p><ul><li><a href="https://docs.agora.io/en/realtime-media/rtc/voice-quickstart/web" target="_blank" rel="noreferrer">https://docs.agora.io/en/realtime-media/rtc/voice-quickstart/web</a></li><li><a href="https://github.com/AgoraIO/Tools/tree/master/DynamicKey/AgoraDynamicKey/java" target="_blank" rel="noreferrer">https://github.com/AgoraIO/Tools/tree/master/DynamicKey/AgoraDynamicKey/java</a></li><li><a href="https://www.agora.io/en/pricing/voice-calling/" target="_blank" rel="noreferrer">https://www.agora.io/en/pricing/voice-calling/</a></li></ul>`,20)])])}const m=a(s,[["render",o]]);export{u as __pageData,m as default};
